package main

import (
	"encoding/json"
	"fmt"
	"reflect"
	"sort"
	"strings"
	"unicode"
)

// header starts every generated file.
const header = "// Code generated by go run ./internal/tower/gen. DO NOT EDIT."

var (
	rawMessageType  = reflect.TypeFor[json.RawMessage]()
	marshalerType   = reflect.TypeFor[json.Marshaler]()
	unmarshalerType = reflect.TypeFor[json.Unmarshaler]()
	enumValuesType  = reflect.TypeFor[interface{ EnumValues() []string }]()
)

// field is one Swift property of a generated struct.
type field struct {
	name     string // Swift property name
	key      string // JSON key
	swift    string // Swift type, without the optional mark
	optional bool
	// empty is the Swift empty literal ("[]" or "[:]") of a non-optional
	// slice or map: Go writes a nil one as null, which decodes as empty.
	empty string
}

// named is one generated Swift type: a struct (fields) or an enum (values).
type named struct {
	goType reflect.Type
	fields []field
	values []string
	enum   bool
}

// collector walks Go types into the named Swift types they need.
type collector struct {
	types map[string]*named
}

// swiftTypes renders TowerTypes.swift for roots and every type they reach.
func swiftTypes(roots []reflect.Type) ([]byte, error) {
	c, err := collect(roots)
	if err != nil {
		return nil, err
	}
	return c.render(), nil
}

func collect(roots []reflect.Type) (*collector, error) {
	c := &collector{types: map[string]*named{}}
	for _, t := range roots {
		if t.Kind() != reflect.Struct {
			return nil, fmt.Errorf("%s: a root must be a struct", t)
		}
		if err := c.addStruct(t); err != nil {
			return nil, err
		}
	}
	return c, nil
}

// claim records t under its name, failing when another Go type has it.
// It reports false when t was already collected.
func (c *collector) claim(t reflect.Type, n *named) (bool, error) {
	if prev, ok := c.types[t.Name()]; ok {
		if prev.goType != t {
			return false, fmt.Errorf("%s and %s both map to the Swift type %s", prev.goType, t, t.Name())
		}
		return false, nil
	}
	c.types[t.Name()] = n
	return true, nil
}

func (c *collector) addStruct(t reflect.Type) error {
	if t.Name() == "" {
		return fmt.Errorf("%s: anonymous structs have no Swift name", t)
	}
	n := &named{goType: t}
	isNew, err := c.claim(t, n)
	if err != nil || !isNew {
		return err
	}
	fields, err := c.fields(t, t.Name())
	if err != nil {
		return err
	}
	seen := map[string]bool{}
	for _, f := range fields {
		if seen["key:"+f.key] {
			return fmt.Errorf("%s: JSON key %q is used twice", t.Name(), f.key)
		}
		if seen["name:"+f.name] {
			return fmt.Errorf("%s: Swift property %s is used twice", t.Name(), f.name)
		}
		seen["key:"+f.key], seen["name:"+f.name] = true, true
	}
	n.fields = fields
	return nil
}

// fields lists t's JSON fields in declaration order, embedded structs
// flattened in place as encoding/json does. owner names t in errors.
func (c *collector) fields(t reflect.Type, owner string) ([]field, error) {
	var out []field
	for i := range t.NumField() {
		sf := t.Field(i)
		tag := sf.Tag.Get("json")
		if tag == "-" {
			continue
		}
		name, opts, _ := strings.Cut(tag, ",")
		if sf.Anonymous && name == "" && sf.Type.Kind() == reflect.Struct {
			embedded, err := c.fields(sf.Type, owner)
			if err != nil {
				return nil, err
			}
			out = append(out, embedded...)
			continue
		}
		if !sf.IsExported() {
			continue
		}
		if name == "" {
			name = sf.Name
		}
		path := owner + "." + sf.Name
		typ, optional := sf.Type, false
		if typ.Kind() == reflect.Pointer {
			typ, optional = typ.Elem(), true
		}
		if o := "," + opts + ","; strings.Contains(o, ",omitempty,") || strings.Contains(o, ",omitzero,") {
			optional = true
		}
		swift, err := c.swiftType(typ, path)
		if err != nil {
			return nil, err
		}
		f := field{name: swiftIdent(lowerCamel(sf.Name)), key: name, swift: swift, optional: optional}
		if !optional && typ != rawMessageType && typ.Kind() == reflect.Slice {
			f.empty = "[]"
		}
		if !optional && typ.Kind() == reflect.Map {
			f.empty = "[:]"
		}
		out = append(out, f)
	}
	return out, nil
}

// swiftType maps one Go type; path names the field in errors.
func (c *collector) swiftType(t reflect.Type, path string) (string, error) {
	if t == rawMessageType {
		return "RawJSON", nil
	}
	if t.Implements(marshalerType) || reflect.PointerTo(t).Implements(unmarshalerType) {
		return "", fmt.Errorf("%s: %s has its own JSON encoding, which the generator cannot map", path, t)
	}
	switch t.Kind() {
	case reflect.String:
		if t.Implements(enumValuesType) {
			return t.Name(), c.addEnum(t)
		}
		return "String", nil
	case reflect.Bool:
		return "Bool", nil
	case reflect.Int:
		return "Int", nil
	case reflect.Int64:
		return "Int64", nil
	case reflect.Float64:
		return "Double", nil
	case reflect.Slice:
		elem, err := c.element(t.Elem(), path)
		if err != nil {
			return "", err
		}
		return "[" + elem + "]", nil
	case reflect.Map:
		if t.Key().Kind() != reflect.String || t.Key().Name() != "string" {
			return "", fmt.Errorf("%s: map key %s is not string", path, t.Key())
		}
		elem, err := c.element(t.Elem(), path)
		if err != nil {
			return "", err
		}
		return "[String: " + elem + "]", nil
	case reflect.Struct:
		return t.Name(), c.addStruct(t)
	default:
		return "", fmt.Errorf("%s: %s has no Swift mapping", path, t)
	}
}

// element maps a slice or map element, which is never optional.
func (c *collector) element(t reflect.Type, path string) (string, error) {
	if t.Kind() == reflect.Pointer {
		return "", fmt.Errorf("%s: a pointer element %s has no Swift mapping", path, t)
	}
	return c.swiftType(t, path)
}

func (c *collector) addEnum(t reflect.Type) error {
	values := reflect.Zero(t).Interface().(interface{ EnumValues() []string }).EnumValues()
	if len(values) == 0 {
		return fmt.Errorf("%s: EnumValues is empty", t)
	}
	cases := map[string]bool{}
	for _, v := range values {
		name := strings.Trim(enumCase(t.Name(), v), "`")
		if name == "" || !unicode.IsLetter([]rune(name)[0]) || cases[name] {
			return fmt.Errorf("%s: value %q has no Swift case of its own", t, v)
		}
		cases[name] = true
	}
	_, err := c.claim(t, &named{goType: t, values: values, enum: true})
	return err
}

// sorted returns the collected types by name.
func (c *collector) sorted() []*named {
	out := make([]*named, 0, len(c.types))
	for _, n := range c.types {
		out = append(out, n)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].goType.Name() < out[j].goType.Name() })
	return out
}

func (c *collector) render() []byte {
	var b strings.Builder
	b.WriteString(header + "\n\nimport Foundation\n")
	for _, n := range c.sorted() {
		b.WriteString("\n")
		if n.enum {
			renderEnum(&b, n)
		} else {
			renderStruct(&b, n)
		}
	}
	return []byte(b.String())
}

func renderStruct(b *strings.Builder, n *named) {
	fmt.Fprintf(b, "public struct %s: Codable, Hashable, Sendable {\n", n.goType.Name())
	if len(n.fields) == 0 {
		b.WriteString("    public init() {}\n}\n")
		return
	}
	for _, f := range n.fields {
		fmt.Fprintf(b, "    public var %s: %s\n", f.name, f.typeText())
	}
	b.WriteString("\n")
	params := make([]string, len(n.fields))
	for i, f := range n.fields {
		params[i] = f.name + ": " + f.typeText()
		if f.optional {
			params[i] += " = nil"
		}
	}
	if len(params) == 1 {
		fmt.Fprintf(b, "    public init(%s) {\n", params[0])
	} else {
		b.WriteString("    public init(\n")
		for i, p := range params {
			sep := ","
			if i == len(params)-1 {
				sep = ""
			}
			fmt.Fprintf(b, "        %s%s\n", p, sep)
		}
		b.WriteString("    ) {\n")
	}
	for _, f := range n.fields {
		fmt.Fprintf(b, "        self.%s = %s\n", strings.Trim(f.name, "`"), f.name)
	}
	b.WriteString("    }\n\n    enum CodingKeys: String, CodingKey {\n")
	for _, f := range n.fields {
		if strings.Trim(f.name, "`") == f.key {
			fmt.Fprintf(b, "        case %s\n", f.name)
		} else {
			fmt.Fprintf(b, "        case %s = %q\n", f.name, f.key)
		}
	}
	b.WriteString("    }\n")
	renderDecoder(b, n.fields)
	b.WriteString("}\n")
}

// renderDecoder writes init(from:) for a struct with a non-optional slice or
// map: a missing or null one (Go's nil) decodes as empty. Other structs keep
// the synthesized decoder.
func renderDecoder(b *strings.Builder, fields []field) {
	needed := false
	for _, f := range fields {
		needed = needed || f.empty != ""
	}
	if !needed {
		return
	}
	b.WriteString("\n    public init(from decoder: Decoder) throws {\n")
	b.WriteString("        let container = try decoder.container(keyedBy: CodingKeys.self)\n")
	for _, f := range fields {
		self := "self." + strings.Trim(f.name, "`")
		switch {
		case f.empty != "":
			fmt.Fprintf(b, "        %s = try container.decodeIfPresent(%s.self, forKey: .%s) ?? %s\n", self, f.swift, f.name, f.empty)
		case f.optional:
			fmt.Fprintf(b, "        %s = try container.decodeIfPresent(%s.self, forKey: .%s)\n", self, f.swift, f.name)
		default:
			fmt.Fprintf(b, "        %s = try container.decode(%s.self, forKey: .%s)\n", self, f.swift, f.name)
		}
	}
	b.WriteString("    }\n")
}

func (f field) typeText() string {
	if f.optional {
		return f.swift + "?"
	}
	return f.swift
}

// enumCase is a value's Swift case name. A value whose name would be
// "unknown" takes the type's name as a suffix, since `unknown(String)` is
// the catch-all case.
func enumCase(typeName, value string) string {
	name := lowerCamel(value)
	if name == "unknown" {
		name += typeName
	}
	return swiftIdent(name)
}

func renderEnum(b *strings.Builder, n *named) {
	name := n.goType.Name()
	fmt.Fprintf(b, "public enum %s: Codable, Hashable, Sendable {\n", name)
	for _, v := range n.values {
		fmt.Fprintf(b, "    case %s\n", enumCase(name, v))
	}
	b.WriteString("    /// A value this build does not know (sent by a newer Watchtower).\n")
	b.WriteString("    case unknown(String)\n\n")
	b.WriteString("    public init(rawValue: String) {\n        switch rawValue {\n")
	for _, v := range n.values {
		fmt.Fprintf(b, "        case %q: self = .%s\n", v, enumCase(name, v))
	}
	b.WriteString("        default: self = .unknown(rawValue)\n        }\n    }\n\n")
	b.WriteString("    public var rawValue: String {\n        switch self {\n")
	for _, v := range n.values {
		fmt.Fprintf(b, "        case .%s: %q\n", enumCase(name, v), v)
	}
	b.WriteString("        case .unknown(let value): value\n        }\n    }\n\n")
	b.WriteString(`    public init(from decoder: Decoder) throws {
        self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }

    public static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.rawValue == rhs.rawValue
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(rawValue)
    }
}
`)
}

// lowerCamel turns a Go name (RequestID, URLPath) or a snake/dotted value
// (not_found, tower.hello) into lowerCamelCase (requestID, urlPath,
// notFound, towerHello).
func lowerCamel(s string) string {
	parts := strings.FieldsFunc(s, func(r rune) bool { return !unicode.IsLetter(r) && !unicode.IsDigit(r) })
	var b strings.Builder
	for i, p := range parts {
		if i == 0 {
			b.WriteString(lowerLead(p))
			continue
		}
		r := []rune(p)
		b.WriteString(string(unicode.ToUpper(r[0])) + string(r[1:]))
	}
	return b.String()
}

// lowerLead lowercases a leading run of capitals, keeping the last one of a
// run that a lowercase letter follows (URLPath → urlPath, ID → id).
func lowerLead(s string) string {
	r := []rune(s)
	n := 0
	for n < len(r) && unicode.IsUpper(r[n]) {
		n++
	}
	if n > 1 && n < len(r) && unicode.IsLower(r[n]) {
		n--
	}
	if n == 0 {
		n = 1
	}
	for i := 0; i < n && i < len(r); i++ {
		r[i] = unicode.ToLower(r[i])
	}
	return string(r)
}

// swiftKeywords are the identifiers a property or case cannot use bare.
var swiftKeywords = map[string]bool{
	"associatedtype": true, "case": true, "class": true, "default": true, "defer": true, "deinit": true,
	"do": true, "else": true, "enum": true, "extension": true, "false": true, "fileprivate": true,
	"for": true, "func": true, "guard": true, "if": true, "import": true, "in": true, "init": true,
	"inout": true, "internal": true, "is": true, "let": true, "nil": true, "operator": true,
	"private": true, "protocol": true, "public": true, "repeat": true, "return": true, "self": true,
	"static": true, "struct": true, "subscript": true, "super": true, "switch": true, "throw": true,
	"throws": true, "true": true, "try": true, "typealias": true, "var": true, "where": true, "while": true,
}

func swiftIdent(s string) string {
	if swiftKeywords[s] {
		return "`" + s + "`"
	}
	return s
}
